mapper.select:
WITH temp_table AS (
SELECT #{glueAreaMachine.mixArea,jdbcType=VARCHAR} mix_area, #{glueAreaMachine.glue,jdbcType=VARCHAR} glue FROM dual
) SELECT STOCK_DATE, MIX_AREA, GLUE, ifnull(sum(STOCK_NUM), 0) STOCK_NUM, ifnull(sum(STOCK_WEIGHT), 0) STOCK_WEIGHT FROM T_GLUE_STOCK WHERE DEL_FLAG= '0' AND STOCK_DATE = #{planDate}
AND (MIX_AREA, GLUE) IN (SELECT MIX_AREA, GLUE FROM temp_table)
GROUP BY STOCK_DATE, MIX_AREA, GLUE

SELECT mix_area, GLUE, recipe_type, sum(ifnull(NIGHT_PLAN_QTY,0)) as DAY_PLAN_QTY
FROM T_GLUE_SCHEDULE_RESULT
WHERE del_flag ='0'
AND schedule_date = #{planDate}
AND mix_area = #{mixArea}
group by mix_area, glue, recipe_type
